// With WithResponseBodyInto the typed result stays populated and the caller's
// target receives the settled volume.
func TestVolumeChangeTypeAndPollResponseBodyInto(t *testing.T) {
	t.Parallel()
	var gets atomic.Int32
	server := newRetypeServer(t, 1, "available", "ssd_hiiops", &gets)
	defer server.Close()
	client := newTaskFlowClient(server)

	var raw []byte
	v, err := client.Cloud.Volumes.ChangeTypeAndPoll(context.Background(), "vol-1", cloud.VolumeChangeTypeParams{
		VolumeType: cloud.VolumeChangeTypeParamsVolumeTypeSsdHiiops,
	}, option.WithResponseBodyInto(&raw))
	if err != nil {
		t.Fatalf("ChangeTypeAndPoll: %v", err)
	}
	if v == nil || v.VolumeType != "ssd_hiiops" {
		t.Fatalf("typed result = %+v, want the settled ssd_hiiops volume", v)
	}
	if !strings.Contains(string(raw), `"ssd_hiiops"`) || strings.Contains(string(raw), `"retyping"`) {
		t.Errorf("caller body = %s, want the settled volume", raw)
	}
}

