func TestVolumeChangeTypeAndPollTimeout(t *testing.T) {
	t.Parallel()
	var gets atomic.Int32
	server := newRetypeServer(t, 1<<30, "available", "ssd_hiiops", &gets)
	defer server.Close()
	client := newTaskFlowClient(server, option.WithPollingTimeoutSeconds(1))

	// Outer guard so a broken timeout fails the test instead of hanging it.
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	_, err := client.Cloud.Volumes.ChangeTypeAndPoll(ctx, "vol-1", cloud.VolumeChangeTypeParams{
		VolumeType: cloud.VolumeChangeTypeParamsVolumeTypeSsdHiiops,
	})
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("err = %v, want context.DeadlineExceeded from the polling timeout", err)
	}
	if ctx.Err() != nil {
		t.Fatal("outer guard deadline fired, not the polling timeout")
	}
}

